SELECT /*selectBuyerWmGrClosingList*/ S.PR_NO -- [01] 주문번호 , S.REF_PR_NO -- [02] 관리번호 , S.PO_NO -- [03] 발주번호 , S.GR_NO -- [04] 입고번호 , S.CHANGE_DATE -- [05] 주문일 , S.PO_CREATE_DATE -- [06] 발주일 , S.BUYER_ITEM_NO -- [07] 품목코드 , S.GR_DATE -- [08] 입고일 , S.DESCRIPTION -- [09] 품명 , S.SPECIFICATION -- [10] 규격 , S.UNIT_PRICE -- [11] 단가 , S.ITEM_AMT -- [12] 입고금액 , S.UNIT_MEASURE -- [13] 단위 , S.PO_ITEM_QTY -- [14] 발주수량 , S.GR_ITEM_QTY -- [15] 입고수량 , S.GR_QTY -- [16] 입고총수량 , S.AGENT_NAME -- [17] 공급사명 , S.CLOSE_STATUS -- [18] 상태 , S.BUYER -- [19] BUYER , S.PR_SEQ -- [20] PR_SEQ , S.PO_SEQ -- [21] PO_SEQ , S.CHANGE_USER_ID -- [22] CHANGE_USER_ID , S.AGENT -- [23] AGENT , S.BYIT_COMORG_CODE -- [24] BYIT_COMORG_CODE , S.CONTRACT_NO -- [25] CONTRACT_NO , S.CONTRACT_SEQ -- [26] CONTRACT_SEQ , S.PX_NO , S.RECV_FLAG , S.CHANGE_USER_DEPT , S.REQ_DEPT_NAME , S.REQ_USER_NAME , S.CATEGORY_NO , (SELECT CASE WHEN A.DEPTH = '1' THEN A.CATEG_NAME WHEN B.DEPTH = '1' THEN B.CATEG_NAME WHEN C.DEPTH = '1' THEN C.CATEG_NAME WHEN D.DEPTH = '1' THEN D.CATEG_NAME END CATEG_NAME FROM ICOMBYCA A --세 , ICOMBYCA B --소 , ICOMBYCA C --중 , ICOMBYCA D --대 WHERE 1=1 AND A.COM_CODE = B.COM_CODE AND A.PID = B.STD_CATEG_ID AND B.COM_CODE = C.COM_CODE(+) AND B.PID = C.STD_CATEG_ID(+) AND C.COM_CODE = D.COM_CODE(+) AND C.PID = D.STD_CATEG_ID(+) AND A.COM_CODE = S.BYIT_COMORG_CODE AND A.STD_CATEG_ID = S.CATEGORY_NO ) AS CATEG_NAME1 /*대분류*/ , (SELECT CASE WHEN A.DEPTH = '2' THEN A.CATEG_NAME WHEN B.DEPTH = '2' THEN B.CATEG_NAME WHEN C.DEPTH = '2' THEN C.CATEG_NAME WHEN D.DEPTH = '2' THEN D.CATEG_NAME END CATEG_NAME FROM ICOMBYCA A --세 , ICOMBYCA B --소 , ICOMBYCA C --중 , ICOMBYCA D --대 WHERE 1=1 AND A.COM_CODE = B.COM_CODE AND A.PID = B.STD_CATEG_ID AND B.COM_CODE = C.COM_CODE(+) AND B.PID = C.STD_CATEG_ID(+) AND C.COM_CODE = D.COM_CODE(+) AND C.PID = D.STD_CATEG_ID(+) AND A.COM_CODE = S.BYIT_COMORG_CODE AND A.STD_CATEG_ID = S.CATEGORY_NO ) AS CATEG_NAME2 /*중분류*/ , (SELECT CASE WHEN A.DEPTH = '3' THEN A.CATEG_NAME WHEN B.DEPTH = '3' THEN B.CATEG_NAME WHEN C.DEPTH = '3' THEN C.CATEG_NAME WHEN D.DEPTH = '3' THEN D.CATEG_NAME END CATEG_NAME FROM ICOMBYCA A --세 , ICOMBYCA B --소 , ICOMBYCA C --중 , ICOMBYCA D --대 WHERE 1=1 AND A.COM_CODE = B.COM_CODE AND A.PID = B.STD_CATEG_ID AND B.COM_CODE = C.COM_CODE(+) AND B.PID = C.STD_CATEG_ID(+) AND C.COM_CODE = D.COM_CODE(+) AND C.PID = D.STD_CATEG_ID(+) AND A.COM_CODE = S.BYIT_COMORG_CODE AND A.STD_CATEG_ID = S.CATEGORY_NO ) AS CATEG_NAME3 /*소분류*/ , S.PR_REF_PR_NO1 , S.PR_REF_PR_NO2 , S.PR_REF_PR_NO3 , S.PR_REF_PR_NO4 , S.ISSUE_ID , S.AR_TAX_BILL_NO , S.PROCESS_TYPE , S.PROCESS_TYPE_NM , S.MAKER_CODE , S.MAKER_NAME , S.BUDGET_DEPT , S.BUDGET_DEPT_NM , S.ACCOUNT_TYPE , S.ACCOUNT_TYPE_NM , F_GET_APRV_USER_LIST(S.BUYER, S.SAVE_FLAG, S.PX_NO, '2') AS APRV_PATH , S.PO_ITEM_AMT , S.AR_ITEM_QTY , S.AR_ITEM_AMT , (SELECT BUY_GREEN_ITEM_NM FROM ICOMBYIT WHERE BUYER_ITEM_NO = S.BUYER_ITEM_NO AND BUYER = S.BYIT_COMORG_CODE ) AS BUY_GREEN_ITEM_NM FROM ( SELECT
/*+ LEADING(PR) INDEX(PR ICOMPRDT_04) USE_NL(PR PO) */
/*+ LEADING(GR) INDEX(GR ICOMGRDT_01) USE_NL(GR PO) */
PR.PR_NO , TRIM(PO.REF_PR_NO) AS REF_PR_NO , PO.PO_NO , GR.GR_NO , PR.CHANGE_DATE , (SELECT PO_CREATE_DATE FROM ICOMPOHD PH WHERE PO.PO_NO = PH.PO_NO AND PO.BUYER = PH.BUYER AND PH.STATUS <> 'D') AS PO_CREATE_DATE , TRIM(PR.BUYER_ITEM_NO) AS BUYER_ITEM_NO , GR.GR_DATE , PR.DESCRIPTION , PR.SPECIFICATION , PO.UNIT_PRICE , GR.ITEM_AMT , PR.UNIT_MEASURE , NVL(PO.ITEM_QTY,0) AS PO_ITEM_QTY , GR.ITEM_QTY AS GR_ITEM_QTY , PO.GR_QTY , DECODE((SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = PO.BUYER), 'N', '코리아이플랫폼(주)' , ( SELECT DECODE(AGENT_OPEN_FLAG,'N','코리아이플랫폼(주)', COM_NAME_LOC) FROM ICOMCMPY A, ICOMPOHD B WHERE PO.BUYER = B.BUYER AND PO.PO_NO = B.PO_NO AND A.COM_CODE = B.AGENT)) AS AGENT_NAME , DECODE(GR.AR_BILL_FLAG, 'N','입고완료',DECODE((SELECT MAIN.ISSUE_ID FROM XXSB_DTI_MAIN MAIN, XXSB_DTI_STATUS STATUS WHERE MAIN.SEQ_ID = GR.AR_TAX_BILL_NO AND MAIN.CONVERSATION_ID = STATUS.CONVERSATION_ID AND STATUS.NTS_SEND_STATUS = '7' AND MAIN.STATUS <> 'D' AND ROWNUM =1), NULL, '마감완료', '국세청전송')) AS CLOSE_STATUS , PR.BUYER , PR.PR_SEQ , PO.PO_SEQ , PR.CHANGE_USER_ID , DECODE((SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = PO.BUYER), 'N', 'KRKORE0001' , ( SELECT DECODE(AGENT_OPEN_FLAG,'N','KRKORE0001', COM_CODE) FROM ICOMCMPY A, ICOMPOHD B WHERE PO.BUYER = B.BUYER AND PO.PO_NO = B.PO_NO AND A.COM_CODE = B.AGENT)) AS AGENT , PR.BYIT_COMORG_CODE , PR.CONTRACT_NO , PR.CONTRACT_SEQ , PR.REF_NO AS PX_NO , PR.RECV_FLAG , PR.CHANGE_USER_DEPT , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND CODE = PR.CHANGE_USER_DEPT AND TYPE = 'C001') AS REQ_DEPT_NAME , (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = PR.CHANGE_USER_ID) AS REQ_USER_NAME , (SELECT CATEGORY_NO FROM ICOMBYIT WHERE BUYER = PR.BYIT_COMORG_CODE AND BUYER_ITEM_NO = PO.BUYER_ITEM_NO) AS CATEGORY_NO , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = PR.BUYER AND CODE = F_SPLIT(PR.REF_PR_NO, '^', 1) AND FLAG = 'Y') AS PR_REF_PR_NO1 , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = PR.BUYER AND CODE = F_SPLIT(PR.REF_PR_NO, '^', 2) AND FLAG = 'Y') AS PR_REF_PR_NO2 , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'Z014' AND COMPANY_CODE = PR.BUYER AND CODE = F_SPLIT(PR.REF_PR_NO, '^', 3) AND FLAG = 'Y') AS PR_REF_PR_NO3 , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'M014' AND COMPANY_CODE = PR.BUYER AND CODE = F_SPLIT(PR.REF_PR_NO, '^', 4) AND FLAG = 'Y') AS PR_REF_PR_NO4 , GR.AR_TAX_BILL_NO , (SELECT MAIN.ISSUE_ID FROM XXSB_DTI_MAIN MAIN, XXSB_DTI_STATUS STATUS WHERE MAIN.SEQ_ID = GR.AR_TAX_BILL_NO AND MAIN.CONVERSATION_ID = STATUS.CONVERSATION_ID AND STATUS.NTS_SEND_STATUS = '7' AND MAIN.STATUS <> 'D' AND ROWNUM = 1) AS ISSUE_ID , PO.PROCESS_TYPE , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M034' AND CODE = PO.PROCESS_TYPE AND FLAG = 'Y') AS PROCESS_TYPE_NM , PO.MAKER_CODE , PO.MAKER_NAME , PR.BUDGET_DEPT , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = PR.BUYER AND CODE = PR.BUDGET_DEPT) AS BUDGET_DEPT_NM , PR.ACCOUNT_TYPE , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'Z014' AND COMPANY_CODE = PR.BUYER AND CODE = PR.ACCOUNT_TYPE) AS ACCOUNT_TYPE_NM , PR.SAVE_FLAG , PO.ITEM_AMT AS PO_ITEM_AMT , DECODE(GR.AR_BILL_FLAG, 'Y', GR.ITEM_QTY, 0) AS AR_ITEM_QTY , DECODE(GR.AR_BILL_FLAG, 'Y', GR.ITEM_AMT, 0) AS AR_ITEM_AMT FROM ICOMPRDT PR, ICOMPODT PO, ICOMGRDT GR WHERE PR.BUYER = #{st_com_code} AND PR.CHANGE_USER_ID = #{st_user_id} AND PR.BUYER = PO.BUYER AND PR.PR_NO = PO.PR_NO AND PR.PR_SEQ = PO.PR_SEQ AND GR.BUYER = PO.BUYER AND GR.PO_NO = PO.PO_NO AND GR.PO_SEQ = PO.PO_SEQ AND PR.STATUS != 'D' AND GR.BUYER=#{st_com_code} AND GR.AR_BILL_FLAG = 'Y'
AND PR.CHANGE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND GR.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND GR.BUYER_ITEM_NO LIKE '%' || #{st_buyer_item_no} || '%'
AND DECODE((SELECT MAIN.ISSUE_ID FROM XXSB_DTI_MAIN MAIN, XXSB_DTI_STATUS STATUS WHERE MAIN.SEQ_ID = GR.AR_TAX_BILL_NO AND MAIN.CONVERSATION_ID = STATUS.CONVERSATION_ID AND STATUS.NTS_SEND_STATUS = '7' AND MAIN.STATUS <> 'D' AND ROWNUM =1), NULL, '마감완료', '국세청전송') = #{st_status}
AND PO.STATUS != 'D' AND GR.STATUS != 'D' ORDER BY 1 ) S

SELECT /*selectBuyerWmGrClosingList_v2*/ S.PR_NO -- [01] 주문번호 , S.REF_PR_NO -- [02] 관리번호 , S.PO_NO -- [03] 발주번호 , S.GR_NO -- [04] 입고번호 , S.CHANGE_DATE -- [05] 주문일 , S.PO_CREATE_DATE -- [06] 발주일 , S.BUYER_ITEM_NO -- [07] 품목코드 , S.GR_DATE -- [08] 입고일 , S.DESCRIPTION -- [09] 품명 , S.SPECIFICATION -- [10] 규격 , S.UNIT_PRICE -- [11] 단가 , S.ITEM_AMT -- [12] 입고금액 , S.UNIT_MEASURE -- [13] 단위 , S.PO_ITEM_QTY -- [14] 발주수량 , S.GR_ITEM_QTY -- [15] 입고수량 , S.GR_QTY -- [16] 입고총수량 , S.AGENT_NAME -- [17] 공급사명 , S.CLOSE_STATUS -- [18] 상태 , S.BUYER -- [19] BUYER , S.PR_SEQ -- [20] PR_SEQ , S.PO_SEQ -- [21] PO_SEQ , S.CHANGE_USER_ID -- [22] CHANGE_USER_ID , S.AGENT -- [23] AGENT , S.BYIT_COMORG_CODE -- [24] BYIT_COMORG_CODE , S.CONTRACT_NO -- [25] CONTRACT_NO , S.CONTRACT_SEQ -- [26] CONTRACT_SEQ , S.PX_NO , S.RECV_FLAG , S.CHANGE_USER_DEPT , S.REQ_DEPT_NAME , S.REQ_USER_NAME , S.CATEGORY_NO , (SELECT CASE WHEN A.DEPTH = '1' THEN A.CATEG_NAME WHEN B.DEPTH = '1' THEN B.CATEG_NAME WHEN C.DEPTH = '1' THEN C.CATEG_NAME WHEN D.DEPTH = '1' THEN D.CATEG_NAME END CATEG_NAME FROM ICOMBYCA A --세 , ICOMBYCA B --소 , ICOMBYCA C --중 , ICOMBYCA D --대 WHERE 1=1 AND A.COM_CODE = B.COM_CODE AND A.PID = B.STD_CATEG_ID AND B.COM_CODE = C.COM_CODE(+) AND B.PID = C.STD_CATEG_ID(+) AND C.COM_CODE = D.COM_CODE(+) AND C.PID = D.STD_CATEG_ID(+) AND A.COM_CODE = S.BYIT_COMORG_CODE AND A.STD_CATEG_ID = S.CATEGORY_NO ) AS CATEG_NAME1 /*대분류*/ , (SELECT CASE WHEN A.DEPTH = '2' THEN A.CATEG_NAME WHEN B.DEPTH = '2' THEN B.CATEG_NAME WHEN C.DEPTH = '2' THEN C.CATEG_NAME WHEN D.DEPTH = '2' THEN D.CATEG_NAME END CATEG_NAME FROM ICOMBYCA A --세 , ICOMBYCA B --소 , ICOMBYCA C --중 , ICOMBYCA D --대 WHERE 1=1 AND A.COM_CODE = B.COM_CODE AND A.PID = B.STD_CATEG_ID AND B.COM_CODE = C.COM_CODE(+) AND B.PID = C.STD_CATEG_ID(+) AND C.COM_CODE = D.COM_CODE(+) AND C.PID = D.STD_CATEG_ID(+) AND A.COM_CODE = S.BYIT_COMORG_CODE AND A.STD_CATEG_ID = S.CATEGORY_NO ) AS CATEG_NAME2 /*중분류*/ , (SELECT CASE WHEN A.DEPTH = '3' THEN A.CATEG_NAME WHEN B.DEPTH = '3' THEN B.CATEG_NAME WHEN C.DEPTH = '3' THEN C.CATEG_NAME WHEN D.DEPTH = '3' THEN D.CATEG_NAME END CATEG_NAME FROM ICOMBYCA A --세 , ICOMBYCA B --소 , ICOMBYCA C --중 , ICOMBYCA D --대 WHERE 1=1 AND A.COM_CODE = B.COM_CODE AND A.PID = B.STD_CATEG_ID AND B.COM_CODE = C.COM_CODE(+) AND B.PID = C.STD_CATEG_ID(+) AND C.COM_CODE = D.COM_CODE(+) AND C.PID = D.STD_CATEG_ID(+) AND A.COM_CODE = S.BYIT_COMORG_CODE AND A.STD_CATEG_ID = S.CATEGORY_NO ) AS CATEG_NAME3 /*소분류*/ , S.PR_REF_PR_NO1 , S.PR_REF_PR_NO2 , S.PR_REF_PR_NO3 , S.PR_REF_PR_NO4 , S.ISSUE_ID , S.AR_TAX_BILL_NO , S.PROCESS_TYPE , S.PROCESS_TYPE_NM , S.MAKER_CODE , S.MAKER_NAME , S.BUDGET_DEPT , S.BUDGET_DEPT_NM , S.ACCOUNT_TYPE , S.ACCOUNT_TYPE_NM , F_GET_APRV_USER_LIST(S.BUYER, S.SAVE_FLAG, S.PX_NO, '2') AS APRV_PATH , S.PO_ITEM_AMT , S.AR_ITEM_QTY , S.AR_ITEM_AMT , (SELECT BUY_GREEN_ITEM_NM FROM ICOMBYIT WHERE BUYER_ITEM_NO = S.BUYER_ITEM_NO AND BUYER = S.BYIT_COMORG_CODE ) AS BUY_GREEN_ITEM_NM FROM ( SELECT
/*+ LEADING(PR) INDEX(PR ICOMPRDT_04) USE_NL(PR PO) */
/*+ LEADING(GR) INDEX(GR ICOMGRDT_01) USE_NL(GR PO) */
PR.PR_NO , TRIM(PO.REF_PR_NO) AS REF_PR_NO , PO.PO_NO , GR.GR_NO , PR.CHANGE_DATE , (SELECT PO_CREATE_DATE FROM ICOMPOHD PH WHERE PO.PO_NO = PH.PO_NO AND PO.BUYER = PH.BUYER AND PH.STATUS <> 'D') AS PO_CREATE_DATE , TRIM(PR.BUYER_ITEM_NO) AS BUYER_ITEM_NO , GR.GR_DATE , PR.DESCRIPTION , PR.SPECIFICATION , PO.UNIT_PRICE , GR.ITEM_AMT , PR.UNIT_MEASURE , NVL(PO.ITEM_QTY,0) AS PO_ITEM_QTY , GR.ITEM_QTY AS GR_ITEM_QTY , PO.GR_QTY , DECODE((SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = PO.BUYER), 'N', '코리아이플랫폼(주)' , ( SELECT DECODE(AGENT_OPEN_FLAG,'N','코리아이플랫폼(주)', COM_NAME_LOC) FROM ICOMCMPY A, ICOMPOHD B WHERE PO.BUYER = B.BUYER AND PO.PO_NO = B.PO_NO AND A.COM_CODE = B.AGENT)) AS AGENT_NAME , DECODE(GR.AR_BILL_FLAG, 'N','입고완료',DECODE((SELECT MAIN.ISSUE_ID FROM XXSB_DTI_MAIN MAIN, XXSB_DTI_STATUS STATUS WHERE MAIN.SEQ_ID = GR.AR_TAX_BILL_NO AND MAIN.CONVERSATION_ID = STATUS.CONVERSATION_ID AND STATUS.NTS_SEND_STATUS = '7' AND MAIN.STATUS <> 'D' AND ROWNUM =1), NULL, '마감완료', '국세청전송')) AS CLOSE_STATUS , PR.BUYER , PR.PR_SEQ , PO.PO_SEQ , PR.CHANGE_USER_ID , DECODE((SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = PO.BUYER), 'N', 'KRKORE0001' , ( SELECT DECODE(AGENT_OPEN_FLAG,'N','KRKORE0001', COM_CODE) FROM ICOMCMPY A, ICOMPOHD B WHERE PO.BUYER = B.BUYER AND PO.PO_NO = B.PO_NO AND A.COM_CODE = B.AGENT)) AS AGENT , PR.BYIT_COMORG_CODE , PR.CONTRACT_NO , PR.CONTRACT_SEQ , PR.REF_NO AS PX_NO , PR.RECV_FLAG , PR.CHANGE_USER_DEPT , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND CODE = PR.CHANGE_USER_DEPT AND TYPE = 'C001') AS REQ_DEPT_NAME , (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = PR.CHANGE_USER_ID) AS REQ_USER_NAME , (SELECT CATEGORY_NO FROM ICOMBYIT WHERE BUYER = PR.BYIT_COMORG_CODE AND BUYER_ITEM_NO = PO.BUYER_ITEM_NO) AS CATEGORY_NO , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = PR.BUYER AND CODE = F_SPLIT(PR.REF_PR_NO, '^', 1) AND FLAG = 'Y') AS PR_REF_PR_NO1 , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = PR.BUYER AND CODE = F_SPLIT(PR.REF_PR_NO, '^', 2) AND FLAG = 'Y') AS PR_REF_PR_NO2 , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'Z014' AND COMPANY_CODE = PR.BUYER AND CODE = F_SPLIT(PR.REF_PR_NO, '^', 3) AND FLAG = 'Y') AS PR_REF_PR_NO3 , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'M014' AND COMPANY_CODE = PR.BUYER AND CODE = F_SPLIT(PR.REF_PR_NO, '^', 4) AND FLAG = 'Y') AS PR_REF_PR_NO4 , GR.AR_TAX_BILL_NO , (SELECT MAIN.ISSUE_ID FROM XXSB_DTI_MAIN MAIN, XXSB_DTI_STATUS STATUS WHERE MAIN.SEQ_ID = GR.AR_TAX_BILL_NO AND MAIN.CONVERSATION_ID = STATUS.CONVERSATION_ID AND STATUS.NTS_SEND_STATUS = '7' AND MAIN.STATUS <> 'D' AND ROWNUM = 1) AS ISSUE_ID , PO.PROCESS_TYPE , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M034' AND CODE = PO.PROCESS_TYPE AND FLAG = 'Y') AS PROCESS_TYPE_NM , PO.MAKER_CODE , PO.MAKER_NAME , PR.BUDGET_DEPT , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = PR.BUYER AND CODE = PR.BUDGET_DEPT) AS BUDGET_DEPT_NM , PR.ACCOUNT_TYPE , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'Z014' AND COMPANY_CODE = PR.BUYER AND CODE = PR.ACCOUNT_TYPE) AS ACCOUNT_TYPE_NM , PR.SAVE_FLAG , PO.ITEM_AMT AS PO_ITEM_AMT , DECODE(GR.AR_BILL_FLAG, 'Y', GR.ITEM_QTY, 0) AS AR_ITEM_QTY , DECODE(GR.AR_BILL_FLAG, 'Y', GR.ITEM_AMT, 0) AS AR_ITEM_AMT FROM ICOMPRDT PR, ICOMPODT PO, ICOMGRDT GR WHERE PR.BUYER = #{st_com_code} AND PR.CHANGE_USER_ID = #{st_user_id} AND PR.BUYER = PO.BUYER AND PR.PR_NO = PO.PR_NO AND PR.PR_SEQ = PO.PR_SEQ AND GR.BUYER = PO.BUYER AND GR.PO_NO = PO.PO_NO AND GR.PO_SEQ = PO.PO_SEQ AND PR.STATUS != 'D' AND GR.BUYER=#{st_com_code}
AND PR.CHANGE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND GR.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND GR.BUYER_ITEM_NO LIKE '%' || #{st_buyer_item_no} || '%'
AND PO.PO_NO LIKE '%' || #{st_po_no} || '%'
AND PR.PR_NO LIKE '%' || #{st_px_no} || '%'
AND DECODE(GR.AR_BILL_FLAG,'N','입고완료', DECODE((SELECT MAIN.ISSUE_ID FROM XXSB_DTI_MAIN MAIN, XXSB_DTI_STATUS STATUS WHERE MAIN.SEQ_ID = GR.AR_TAX_BILL_NO AND MAIN.CONVERSATION_ID = STATUS.CONVERSATION_ID AND STATUS.NTS_SEND_STATUS = '7' AND MAIN.STATUS <> 'D' AND ROWNUM =1), NULL, '마감완료', '국세청전송')) = #{st_status}
AND PO.STATUS != 'D' AND GR.STATUS != 'D' ORDER BY 1 ) S
